import { readFile } from "node:fs/promises";
import { expect, test } from "@playwright/test";

// This project requires a running local validator and the public evidence report
// generated by e2e/validator/run.ts. It never substitutes recorded RPC responses.
const reportPath = process.env.WEB_VALIDATOR_REPORT;
const rpc = process.env.WEB_VALIDATOR_RPC_URL;
if (!reportPath || !rpc)
  throw new Error(
    "The W3 validator project requires WEB_VALIDATOR_REPORT and WEB_VALIDATOR_RPC_URL from the local runner",
  );
const endpoint = new URL(rpc);
if (
  endpoint.protocol !== "http:" ||
  endpoint.hostname !== "127.0.0.1" ||
  endpoint.username ||
  endpoint.password
)
  throw new Error("W3 only accepts the disposable localhost validator RPC");
const report = JSON.parse(await readFile(reportPath, "utf8")) as {
  provenance: { kind: string; provider: string };
  pulls: { address: string; seq: string; callback: string }[];
};
if (report.provenance.kind !== "fresh local-validator transactions")
  throw new Error("W3.09 requires a fresh 100-Pull report");

test("W3.09: the Verify page checks every fresh local-validator Pull", async ({
  page,
  request,
}) => {
  test.setTimeout(180_000);
  expect(report.pulls).toHaveLength(100);
  await page.emulateMedia({ reducedMotion: "reduce" });
  // Keep the same-origin browser contract; forward bytes to the live local bank.
  // Admission of the production API is tested separately by its router suite.
  await page.route("**/api/rpc", async (route) => {
    const response = await request.post(endpoint.href, {
      data: route.request().postDataBuffer() ?? undefined,
      headers: { "content-type": "application/json" },
    });
    await route.fulfill({
      status: response.status(),
      body: await response.body(),
      contentType: "application/json",
    });
  });
  for (const pull of report.pulls) {
    await page.goto(`/verify/${pull.address}`);
    const verified = page.locator(
      `[data-public-view="verify"] [data-verify-seq="${pull.seq}"][data-verify-state="verified"]`,
    );
    await expect(verified).toBeVisible();
    await expect(
      page.locator(`a[href*="${pull.callback}"]`).first(),
    ).toBeVisible();
  }
});
